begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('event-close-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','event-close-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','event-close-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;
set local role authenticated;
select pg_temp.actor('owner');
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('account'),'kind','account','name','Banco fictício'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('income'),'kind','category','name','Receita fictícia','direction','income'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('expense'),'kind','category','name','Taxa fictícia','direction','expense'));
select public.finance_digital(pg_temp.fi('org'),pg_temp.fi('a'),'purpose',jsonb_build_object('id',pg_temp.fi('purpose'),'version',0,'name','Oferta fictícia','origin','event','account',pg_temp.fi('account'),'category',pg_temp.fi('income'),'feeCategory',pg_temp.fi('expense'),'refundCategory',pg_temp.fi('expense'),'creditCategory',pg_temp.fi('income'),'active',true));
reset role;
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured) values(pg_temp.fi('receiver'),pg_temp.fi('org'),pg_temp.fi('a'),'mercado_pago','production','configured','123','Conta fictícia',true,array[pg_temp.fi('a')],pg_temp.fi('account'),pg_temp.fi('owner'),now()+interval '1 day',array['pix'],true,true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.member_payment_publish(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('purpose'),pg_temp.fi('receiver'),true)$$,'publica finalidade com destino válido');

reset role;
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity,status) values(pg_temp.fi('event2'),pg_temp.fi('org'),pg_temp.fi('a'),'Tickets fictícios etapa 2','event',now()+interval '2 days',now()+interval '3 days',10,'published');
create function pg_temp.v() returns integer language sql security definer set search_path='' as $$select version from private.church_app_events where id=pg_temp.fi('event2')$$;
create function pg_temp.admin2(a text,i uuid default null,d jsonb default '{}') returns jsonb language sql as $$select public.event_ticket_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),a,i,pg_temp.v(),d)$$;
create function pg_temp.settings2() returns jsonb language sql as $$select jsonb_build_object('enabled',true,'allow_guests',true,'show_remaining',true,'purpose',pg_temp.fi('purpose'),'receiving_unit',pg_temp.fi('a'),'reservation_hours',24,'questions','[]'::jsonb)$$;
create function pg_temp.type2(n text,mode text,price integer,quantity integer) returns jsonb language sql as $$select jsonb_build_object('name',n,'mode',mode,'price',price::text,'quantity',quantity::text,'starts',now()-interval '1 day','ends',now()+interval '1 day','active',true,'per_user','2','per_cpf','','audience','public','audience_units','[]'::jsonb,'position',0)$$;
create function pg_temp.payload2(t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select jsonb_build_object('buyerName','Pessoa fictícia','buyerEmail',buyer||'-family@example.invalid','emailConfirmation',buyer||'-family@example.invalid','coupon','','intent',intent,'items',jsonb_build_array(jsonb_build_object('type',pg_temp.fi(t),'name','Participante fictício','email','','cpf','','phone','','answers','{}'::jsonb)))$$;
create function pg_temp.buy2(id text,t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi(id),case when buyer='guest' then null else pg_temp.fi(buyer) end,repeat('a',64),pg_temp.payload2(t,buyer,intent),repeat('f',64))$$;

set local role authenticated;select pg_temp.actor('owner');
select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"allow_guests":false}');
select pg_temp.admin2('type',pg_temp.fi('free'),pg_temp.type2('Gratuito fictício','free',0,2));
select pg_temp.admin2('type',pg_temp.fi('paid'),pg_temp.type2('Pago fictício','paid',1000,3));
select pg_temp.admin2('type',pg_temp.fi('reserve'),pg_temp.type2('Reserva fictícia','reservation',1000,2));
create function pg_temp.staff(a text,id text default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.event_staff_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),a,case when id is null then null else pg_temp.fi(id) end,v,d)$$;
select lives_ok($$select pg_temp.staff('create','free-staff',null,pg_temp.payload2('free','guest'))$$,'secretaria registra gratuito mesmo sem visitantes no link público');
select lives_ok($$select pg_temp.staff('create','free-staff',null,pg_temp.payload2('free','guest'))$$,'repetição da mesma solicitação não duplica estoque');
select throws_ok($$select pg_temp.staff('create','free-staff',null,pg_temp.payload2('free','second'))$$,'40001','event_staff_changed','repetição divergente recusada');
select lives_ok($$select pg_temp.staff('create','paid-staff',null,pg_temp.payload2('paid','second'))$$,'pago pela secretaria mantém pagamento pendente');
select pg_temp.actor('member');
select throws_ok($$select pg_temp.staff('read')$$,'42501',null,'membro não acessa secretaria');
select pg_temp.actor('owner');
select throws_ok($$select public.event_staff_admin(pg_temp.fi('org'),pg_temp.fi('b'),pg_temp.fi('event2'),'read')$$,'42501',null,'igreja incorreta não acessa evento');
reset role;
select is((select count(*)::integer from private.event_ticket_items where order_id=pg_temp.fi('free-staff')),1,'uma vaga consumida');
select is((select state from private.event_ticket_orders where id=pg_temp.fi('paid-staff')),'holding','pedido pago não é confirmado pela secretaria');
select is((select checkout_state from private.event_ticket_orders where id=pg_temp.fi('paid-staff')),'reserved','nenhuma chamada ao provedor feita no banco');
select set_config('close.item',(select id::text from private.event_ticket_items where order_id=pg_temp.fi('free-staff')),true);
select set_config('close.token',(select token::text from private.event_receipt_links where order_id=pg_temp.fi('free-staff')),true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.event_staff_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'edit',current_setting('close.item')::uuid,1,'{"name":"Nome atualizado fictício","email":"","cpf":"","phone":"","answers":{},"reason":"Correção solicitada pelo titular"}')$$,'edição controlada e justificada');
select throws_ok($$select public.event_staff_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'edit',current_setting('close.item')::uuid,1,'{"name":"Outra alteração","email":"","cpf":"","phone":"","answers":{},"reason":"Alteração concorrente"}')$$,'40001','event_staff_changed','versão antiga não sobrescreve alteração');
select lives_ok($$select pg_temp.staff('email','free-staff',null,jsonb_build_object('request',pg_temp.fi('email1')))$$,'reenvio enfileirado para comprador original');
select lives_ok($$select pg_temp.staff('email','free-staff',null,jsonb_build_object('request',pg_temp.fi('email1')))$$,'mesmo reenvio não duplica entrega');
select throws_ok($$select pg_temp.staff('email','free-staff',null,jsonb_build_object('request',pg_temp.fi('email2')))$$,'40001','event_receipt_rate_limit','reenvio repetido exige intervalo');
select is((public.event_insights(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'report')->'metrics'->>'confirmed')::integer,1,'relatório conta confirmado sem incluir pago pendente');
select is((public.event_insights(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'finance',jsonb_build_object('from',current_date+20,'to',current_date+21))->'summary'->>'orders')::integer,0,'período filtra lista e totais financeiros');
select throws_ok($$select public.event_insights(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'finance','{"from":"2027-12-31","to":"2027-01-01"}')$$,'22023',null,'período invertido recusado');
reset role;
select is((select count(*)::integer from private.event_receipt_deliveries where order_id=pg_temp.fi('free-staff')),1,'uma entrega transacional');
select is((select total::integer from private.event_ticket_orders where id=pg_temp.fi('free-staff')),0,'edição não altera preço');
set local role anon;
select is(public.member_event_receipt(current_setting('close.token')::uuid)->'items'->0->>'name','Nome atualizado fictício','comprovante reflete a última edição');
select ok(not(public.member_event_receipt(current_setting('close.token')::uuid)::text like '%buyerEmail%'),'link não expõe e-mail do comprador');
select is(public.member_event_receipt(pg_temp.fi('missing')),null::jsonb,'token inexistente não revela pedido');
select ok(not has_function_privilege('anon','public.event_staff_admin(uuid,uuid,uuid,text,uuid,integer,jsonb)','execute'),'visitante sem acesso à secretaria');
select ok(not has_function_privilege('authenticated','public.event_receipt_payment(uuid)','execute'),'segredo do pagamento acessível somente ao servidor');
reset role;
select is(public.event_receipt_work('claim',pg_temp.fi('org'),pg_temp.fi('event2'))->'items'->0->>'recipient','guest-family@example.invalid','envio usa exclusivamente o e-mail registrado do comprador');
select is(jsonb_array_length(public.event_receipt_work('claim',pg_temp.fi('org'),pg_temp.fi('event2'))->'items'),0,'entrega em andamento não é reenviada');
-- An ongoing event remains open until the ticket deadline, unlike a sale order deadline.
update private.church_app_events set starts_at=now()-interval '1 hour' where id=pg_temp.fi('event2');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select pg_temp.staff('create','ongoing-staff',null,pg_temp.payload2('reserve','guest','reserve'))$$,'evento em andamento aceita reserva dentro da validade do ticket');
reset role;
select ok((select expires_at>now() from private.event_ticket_orders where id=pg_temp.fi('ongoing-staff')),'reserva durante evento mantém validade futura');
select ok(position('else e.ends_at end' in pg_get_functiondef('private.event_ticket_checkout(uuid,text,uuid,uuid,text,jsonb,text)'::regprocedure))>0,'checkout respeita término do evento');
select ok(position('else e.ends_at end' in pg_get_functiondef('private.event_ticket_delivery(uuid,text,jsonb)'::regprocedure))>0,'envio ao provedor respeita término do evento');
select ok(position('else e.ends_at end' in pg_get_functiondef('private.event_ticket_payment_apply()'::regprocedure))>0,'confirmação verificada respeita término do evento');
set local role authenticated;select pg_temp.actor('owner');
select throws_ok($$select public.member_event_experience(pg_temp.fi('event2'),5,'Muito bom')$$,'42501',null,'evento ainda não encerrado não recebe avaliação');
reset role;
update private.church_app_events set ends_at=now()-interval '1 minute' where id=pg_temp.fi('event2');
update private.event_ticket_orders set user_id=pg_temp.fi('member') where id=pg_temp.fi('free-staff');
set local role authenticated;select pg_temp.actor('member');
select lives_ok($$select public.member_event_experience(pg_temp.fi('event2'),5,'Encontro fictício muito bom')$$,'participante confirmado avalia após o evento');
select lives_ok($$select public.member_event_experience(pg_temp.fi('event2'),4,'Avaliação atualizada')$$,'uma avaliação por pessoa pode ser atualizada');
select pg_temp.actor('second');
select throws_ok($$select public.member_event_experience(pg_temp.fi('event2'),5,'Sem pagamento')$$,'42501',null,'pedido pendente não autoriza avaliar');
select pg_temp.actor('owner');
select is((public.event_insights(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'report')->'ratings'->>'total')::integer,1,'relatório não duplica avaliações');

reset role;
insert into private.learning_programs(id,organization_id,unit_id,kind,title,steps,status,created_by,nonce) values(pg_temp.fi('journey'),pg_temp.fi('org'),pg_temp.fi('a'),'journey','Jornada fictícia','[{"title":"Etapa","body":"Aprender","href":"","readings":[]}]','published',pg_temp.fi('owner'),'close-journey'),(pg_temp.fi('other-journey'),pg_temp.fi('org'),pg_temp.fi('b'),'journey','Outra igreja','[{"title":"Etapa","body":"Aprender","href":"","readings":[]}]','published',pg_temp.fi('owner'),'close-other');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.event_insights(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'journeys_save',jsonb_build_object('programs',jsonb_build_array(pg_temp.fi('journey'))))$$,'vincula jornada publicada na igreja');
select throws_ok($$select public.event_insights(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'journeys_save',jsonb_build_object('programs',jsonb_build_array(pg_temp.fi('other-journey'))))$$,'42501','event_journey_denied','não vincula jornada de outra igreja');
select lives_ok($$select public.event_operations_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'message_save',pg_temp.fi('media'),null,jsonb_build_object('title','Aviso com mídia','body','Teste fictício','audience','confirmed','email',true,'scheduled',now(),'image','https://example.com/banner.jpg','redirect','https://example.com/aviso'))$$,'aviso aceita imagem e link HTTPS');
select throws_ok($$select public.event_operations_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'message_save',pg_temp.fi('unsafe-media'),null,jsonb_build_object('title','Aviso inválido','body','Teste fictício','audience','confirmed','email',false,'scheduled',now(),'image','javascript:alert(1)','redirect',''))$$,'22023',null,'recusa mídia com protocolo executável');
select lives_ok($$select public.event_operations_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),'message_schedule',pg_temp.fi('media'),1)$$,'programa aviso validado');
select pg_temp.actor('member');
select is(jsonb_array_length(public.member_event_experience(pg_temp.fi('event2'))->'journeys'),1,'jornada vinculada aparece na experiência');
select is(public.member_event_experience(pg_temp.fi('event2'))->'messages'->0->>'image_url','https://example.com/banner.jpg','destinatário elegível recebe mídia');
select pg_temp.actor('second');
select is(jsonb_array_length(public.member_event_experience(pg_temp.fi('event2'))->'messages'),0,'pedido não confirmado não recebe aviso dos confirmados');
select finish();rollback;

